import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_PARCELA, MODELO_HUERTO, TABLA_PARCELAS } from '../../models/huerto-parcela.model.mjs';

export async function buscarHuertoRepository(huertoId) {
  const { Item } = await MODELO_HUERTO.build(GetItemCommand)
    .key({ huertoId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarHuertoRepository(huertoId, minimo) {
  const { Items = [] } = await TABLA_PARCELAS.build(QueryCommand)
    .entities(MODELO_PARCELA)
    .query({ index: 'PorHuerto', partition: huertoId })
    .options({ filters: { Parcela: { attr: 'superficieM2', gte: minimo } } })
    .send();
  return Items;
}
